"""Original graph reader safety and offscreen topology widget behavior."""
import hashlib
import os
import tempfile
import unittest
from pathlib import Path
from unittest import mock
from xml.etree import ElementTree

from salam_workbench.workbench_topology import load_topology, sanitize_svg

GRAPHVIZ = b"""<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN"
 "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd">
<!-- Generated by graphviz; actual SimObject names are retained. -->
<svg width="300pt" height="120pt" viewBox="0 0 300 120"
 xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
 <g id="graph0" class="graph" transform="translate(4 116)">
  <title>config</title>
  <polygon fill="white" stroke="transparent" points="-4,4 -4,-116 296,-116 296,4"/>
  <g id="node1"><title>system.gemm_clstr.gemm</title>
   <ellipse fill="none" stroke="black" cx="130" cy="-60" rx="110" ry="18"/>
   <text text-anchor="middle" x="130" y="-56" font-family="Times,serif" font-size="14">system.gemm_clstr.gemm</text>
  </g>
 </g>
</svg>"""


class TopologyReaderTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix="salam-topology-fixture-")
        self.addCleanup(temporary.cleanup)
        self.project = Path(temporary.name)
        (self.project / "evidence/run/simulator").mkdir(parents=True)

    def artifact(
        self, name="config.dot.svg", payload=GRAPHVIZ, root="evidence/run/simulator"
    ):
        path = self.project / root / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(payload)
        return {
            "name": "simulator/" + name,
            "path": str(path),
            "status": "hash_verified",
            "sha256": hashlib.sha256(payload).hexdigest(),
        }

    def test_graphviz_doctype_is_accepted_without_external_fetch(self):
        sanitized = sanitize_svg(GRAPHVIZ)
        self.assertNotIn(b"<!DOCTYPE", sanitized)
        root = ElementTree.fromstring(sanitized)
        self.assertTrue(root.tag.endswith("}svg"))
        self.assertIn(b"system.gemm_clstr.gemm", sanitized)

    def test_active_foreign_content_and_external_references_are_removed(self):
        unsafe = b"""<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" onload="bad()">
          <script>bad()</script><foreignObject><div>foreign</div></foreignObject>
          <image href="file:///private.png"/><style>@import 'https://example.test/a.css';</style>
          <a xlink:href="https://example.test"><text>Safe label</text></a>
          <use href="#local"/><rect fill="url(https://example.test/paint)" style="background:url(file:///x)"/>
        </svg>"""
        sanitized = sanitize_svg(unsafe)
        self.assertNotIn(b"bad()", sanitized)
        self.assertNotIn(b"example.test", sanitized)
        self.assertNotIn(b"file:///", sanitized)
        self.assertNotIn(b"foreignObject", sanitized)
        self.assertIn(b"Safe label", sanitized)
        self.assertIn(b'href="#local"', sanitized)

    def test_entity_internal_subset_and_non_svg_are_rejected(self):
        values = (
            b'<!DOCTYPE svg [<!ENTITY x "expanded">]><svg>&x;</svg>',
            b'<!DOCTYPE svg SYSTEM "file:///private.dtd"><svg/>',
            b"<html><body>not svg</body></html>",
            b"<svg>\x00</svg>",
        )
        for payload in values:
            with self.subTest(payload=payload):
                with self.assertRaises(ValueError):
                    sanitize_svg(payload)

    def test_only_hash_verified_original_graph_is_loaded(self):
        artifact = self.artifact()
        before = Path(artifact["path"]).read_bytes()
        result = load_topology({"artifacts": [artifact]}, self.project)
        self.assertEqual(result["state"], "ready")
        self.assertEqual(result["sha256"], artifact["sha256"])
        self.assertEqual(Path(artifact["path"]).read_bytes(), before)
        self.assertIn("not runtime activity", result["scope"])
        artifact["status"] = "present_unbound"
        self.assertEqual(
            load_topology({"artifacts": [artifact]}, self.project)["state"],
            "unavailable",
        )

    def test_changed_graph_cannot_reuse_earlier_verified_status(self):
        artifact = self.artifact()
        Path(artifact["path"]).write_bytes(b'<svg xmlns="http://www.w3.org/2000/svg"/>')
        result = load_topology({"artifacts": [artifact]}, self.project)
        self.assertEqual(result["state"], "unavailable")
        self.assertIsNone(result["svg_bytes"])
        self.assertTrue(any("SHA-256" in issue for issue in result["issues"]))

    def test_graph_must_stay_inside_evidence_or_runs(self):
        outside = self.artifact(root="outside")
        self.assertEqual(
            load_topology({"artifacts": [outside]}, self.project)["state"],
            "unavailable",
        )
        inside_runs = self.artifact(root="runs/one/simulator")
        self.assertEqual(
            load_topology({"artifacts": [inside_runs]}, self.project)["state"], "ready"
        )

    def test_symlinked_graph_is_rejected_even_with_matching_digest(self):
        artifact = self.artifact()
        # Exercise the safe-path symlink branch without needing Windows's
        # optional symbolic-link creation privilege in pure parser checks.
        original = Path.is_symlink
        selected = Path(artifact["path"])
        with mock.patch.object(
            Path, "is_symlink", lambda path: path == selected or original(path)
        ):
            self.assertEqual(
                load_topology({"artifacts": [artifact]}, self.project)["state"],
                "unavailable",
            )

    def test_missing_or_ambiguous_graph_never_selects_an_arbitrary_file(self):
        artifact = self.artifact()
        self.assertEqual(
            load_topology({"artifacts": []}, self.project)["state"], "unavailable"
        )
        self.assertEqual(
            load_topology({"artifacts": [artifact, artifact]}, self.project)["state"],
            "unavailable",
        )

    def test_companions_are_hash_verified_and_from_the_same_run(self):
        svg = self.artifact()
        dot = self.artifact("config.dot", b"digraph config { system -> accelerator }")
        pdf = self.artifact("config.dot.pdf", b"%PDF-1.4\nfixture")
        result = load_topology({"artifacts": [svg, dot, pdf]}, self.project)
        self.assertEqual(result["state"], "ready")
        self.assertEqual(result["dot"]["path"], dot["path"])
        self.assertEqual(result["pdf"]["path"], pdf["path"])
        dot["path"] = self.artifact(
            "config.dot", b"other", root="evidence/other/simulator"
        )["path"]
        result = load_topology({"artifacts": [svg, dot]}, self.project)
        self.assertIsNone(result["dot"])

    def test_size_limit_is_enforced_before_parser(self):
        artifact = self.artifact()
        with mock.patch("salam_workbench.workbench_topology.MAX_SVG_BYTES", 10):
            self.assertEqual(
                load_topology({"artifacts": [artifact]}, self.project)["state"],
                "unavailable",
            )
            with self.assertRaises(ValueError):
                sanitize_svg(GRAPHVIZ)


class TopologyWidgetTests(unittest.TestCase):
    setUp = TopologyReaderTests.setUp
    artifact = TopologyReaderTests.artifact

    @classmethod
    def setUpClass(cls):
        os.environ.setdefault("QT_QPA_PLATFORM", "offscreen")
        try:
            from PySide6.QtWidgets import QApplication

            from salam_workbench.workbench_topology import TopologyPanel
        except ImportError as error:
            raise unittest.SkipTest("Qt SVG widgets unavailable: " + str(error))
        cls.app = QApplication.instance() or QApplication([])
        cls.panel_class = TopologyPanel

    def test_widget_zooms_and_clears_old_graph_on_missing_result(self):
        panel = self.panel_class(self.project)
        self.addCleanup(panel.close)
        panel.resize(700, 400)
        panel.show_run({"artifacts": [self.artifact()]})
        self.app.processEvents()
        self.assertIsNotNone(panel.graph_item)
        self.assertTrue(panel.fit_btn.isEnabled())
        panel.actual_btn.click()
        self.assertAlmostEqual(panel.view.transform().m11(), 1.0)
        panel.zoom_in_btn.click()
        self.assertGreater(panel.view.transform().m11(), 1.0)
        panel.zoom_out_btn.click()
        self.assertAlmostEqual(panel.view.transform().m11(), 1.0)
        panel.show_run({"artifacts": []})
        self.assertIsNone(panel.graph_item)
        self.assertEqual(len(panel.scene.items()), 0)
        self.assertFalse(panel.fit_btn.isEnabled())
        self.assertFalse(panel.dot_btn.isEnabled())
        self.assertEqual(panel.caption.text(), "")

    def test_original_open_action_rechecks_hash(self):
        svg = self.artifact()
        dot = self.artifact("config.dot", b"digraph config {}")
        panel = self.panel_class(self.project)
        self.addCleanup(panel.close)
        panel.show_run({"artifacts": [svg, dot]})
        Path(dot["path"]).write_bytes(b"changed")
        with mock.patch("PySide6.QtGui.QDesktopServices.openUrl") as open_url:
            panel.dot_btn.click()
            open_url.assert_not_called()
        self.assertIn("SHA-256", panel.status.text())


if __name__ == "__main__":
    unittest.main()
